import em from '@$$emscript'
export const $U = em.$declare('COMPOSITE')

export function em$generate() {
    let out = $outfile('emm.distro.9305/REGS.hpp')
    out.addFile('../emm.9305/emm.distro.9305/REGS.hpp.txt')
    out.close()
}

